/**
 * @file probe_verifier_test.cpp
 * @brief ECDSA P-256 probe signature verification with Security.framework, keys generated by openssl.
 */
#include <gtest/gtest.h>

#include <fstream>
#include <iterator>

#include "ieso/macos/ecdsa_probe_verifier.hpp"
#include "ieso/macos/subprocess.hpp"
#include "test_util.hpp"

using namespace ieso;
using namespace ieso::macos;
using namespace ieso::test;
using namespace std::chrono_literals;

namespace {
/// @brief Runs a command and asserts success. @param[in] argv Command. @return Output.
std::string sh(const std::vector<std::string>& argv) {
  std::string out;
  int code = -1;
  EXPECT_EQ(Subprocess::Run(argv, 30s, out, code), SRESULT::Ok);
  EXPECT_EQ(code, 0) << out;
  return out;
}
/// @brief Reads a whole file. @param[in] p Path. @return Bytes.
std::string slurp(const std::filesystem::path& p) {
  std::ifstream f(p, std::ios::binary);
  return std::string((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());
}
}  // namespace

/// A signature by the pinned key verifies; a tampered message or another key's signature does not.
TEST(ProbeVerifier, EcdsaP256) {
  TempDir tmp;
  std::filesystem::path d;
  ASSERT_EQ(tmp.path(d), SRESULT::Ok);
  for (const char* k : {"a", "b"}) {
    sh({"/usr/bin/openssl", "ecparam", "-name", "prime256v1", "-genkey", "-noout", "-out", (d / (std::string(k) + ".key")).string()});
    sh({"/usr/bin/openssl", "ec", "-in", (d / (std::string(k) + ".key")).string(), "-pubout", "-out",
        (d / (std::string(k) + ".pub.pem")).string()});
  }
  const std::string msg = "v1|rq-1|ep-demo|net.config|inc-1|1767225600000|1767225720000";
  { std::ofstream(d / "msg.txt", std::ios::binary) << msg; }
  sh({"/usr/bin/openssl", "dgst", "-sha256", "-sign", (d / "a.key").string(), "-out", (d / "sig.der").string(),
      (d / "msg.txt").string()});
  const std::string sig = slurp(d / "sig.der");

  std::unique_ptr<EcdsaProbeVerifier> va, vb;
  ASSERT_EQ(EcdsaProbeVerifier::Create((d / "a.pub.pem").string(), va), SRESULT::Ok);
  ASSERT_EQ(EcdsaProbeVerifier::Create((d / "b.pub.pem").string(), vb), SRESULT::Ok);
  bool ok = false;
  ASSERT_EQ(va->verify(msg, sig, ok), SRESULT::Ok);
  EXPECT_TRUE(ok);
  ASSERT_EQ(va->verify(msg + "x", sig, ok), SRESULT::Ok);
  EXPECT_FALSE(ok);  // tampered request
  ASSERT_EQ(vb->verify(msg, sig, ok), SRESULT::Ok);
  EXPECT_FALSE(ok);  // signed by a different key
  ASSERT_EQ(va->verify(msg, "garbage", ok), SRESULT::Ok);
  EXPECT_FALSE(ok);
  std::unique_ptr<EcdsaProbeVerifier> bad;
  EXPECT_EQ(EcdsaProbeVerifier::Create((d / "missing.pem").string(), bad), SRESULT::NotFound);
  EXPECT_EQ(EcdsaProbeVerifier::Create((d / "msg.txt").string(), bad), SRESULT::CorruptData);
}
